'use strict';
// Datos sintéticos para explorar navegación. No hay servicios, IA, captura ni persistencia de datos personales.
const params = new URLSearchParams(location.search);
if (params.get('view') === 'wireframe') document.body.classList.add('wireframe');
const app = document.getElementById('app');
const demo = {screen:'landing', title:'Mi próxima exposición', mode:'Exposición', duration:5, segment:'Ciclos 1–5', goal:'Reducir muletillas', mic:false, consent:false, paused:false, disconnected:false, muted:false, completed:false, analysisFailed:false, insufficient:false, deleted:false, shared:false, revoked:false, material:'', optionalEmail:true, planDone:false};
const screenNames = {landing:'Inicio público',register:'Crear cuenta',login:'Iniciar sesión',recovery:'Recuperar acceso',dashboard:'Inicio',profile:'Perfil',setup:'Nueva práctica',microphone:'Preparar audio',live:'Práctica en vivo',processing:'Estado del análisis',report:'Reporte',history:'Historial',progress:'Progreso',compare:'Comparar sesiones',plan:'Plan de práctica',privacy:'Privacidad y acceso',shared:'Reporte compartido',preferences:'Notificaciones',terms:'Términos de uso'};
const nav = [['dashboard','◫','Dashboard'],['setup','＋','Nueva sesión'],['history','◷','Sesiones'],['progress','↗','Progreso'],['profile','○','Perfil']];
const escapeHtml = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button = (label,action,style='') => `<button type="button" data-action="${action}" class="${style}">${label}</button>`;
const goButton = (label,screen,style='') => button(label,`go:${screen}`,style);
const brand = () => `<a class="brand" href="#landing"><span class="brand-icon" aria-hidden="true">T</span>Talki</a>`;
const field = (label,name,type='text',value='',extra='') => `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${escapeHtml(value)}" ${extra}></div>`;
const head = (title,subtitle,actions='') => `<div class="page-title"><div><div class="eyebrow">Tu espacio de práctica</div><h1 tabindex="-1">${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;
const note = text => `<div class="notice">${text}</div>`;
const dimensions = (partial=false) => ['Fluidez','Claridad','Volumen','Vocabulario','Confianza estimada'].map((name,i)=>`<div class="dimension"><div class="flex-between"><span>${name}</span><strong>${partial && i>1?'Sin evidencia':[76,84,81,73,79][i]+'/100'}</strong></div><div class="dimension-track"><i style="width:${partial&&i>1?0:[76,84,81,73,79][i]}%"></i></div></div>`).join('');
const wave = () => `<div class="wave" aria-hidden="true">${Array.from({length:48},(_,i)=>`<i style="height:${15+Math.abs(Math.sin(i*1.8))*65+Math.abs(Math.cos(i*.4))*25}px"></i>`).join('')}</div>`;
const chart = () => `<svg class="chart" viewBox="0 0 560 220" role="img" aria-label="Ejemplo ficticio: puntuaciones 65, 71, 68, 76 y 79. No representa resultados reales."><g stroke="var(--border)"><path d="M45 30H535M45 80H535M45 130H535M45 180H535"/></g><g><text x="12" y="34">90</text><text x="12" y="84">80</text><text x="12" y="134">70</text><text x="12" y="184">60</text></g><path d="M55 155L170 125L285 140L400 100L520 85L520 180L55 180Z" fill="var(--muted)"/><path d="M55 155L170 125L285 140L400 100L520 85" fill="none" stroke="var(--chart-1)" stroke-width="3"/><g fill="var(--chart-1)">${[[55,155],[170,125],[285,140],[400,100],[520,85]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="5"/>`).join('')}</g><g><text x="44" y="208">S1</text><text x="159" y="208">S2</text><text x="274" y="208">S3</text><text x="389" y="208">S4</text><text x="509" y="208">S5</text></g></svg>`;
function sessionRows(){
  if(demo.deleted) return `<div class="empty"><h3>La sesión fue retirada</h3><p>El acceso queda bloqueado. La purga física está pendiente de confirmación en este ejemplo.</p>${goButton('Crear una práctica','setup')}</div>`;
  return [['Exposición: proyecto de curso','Exposición · 5 min · Ejemplo ficticio','79'],['Presentación de idea','Pitch · 3 min · Ejemplo ficticio','76'],['Ensayo inicial','Exposición · 5 min · Ejemplo ficticio','68']].map(([title,meta,score])=>`<div class="session-row"><div><h3>${title}</h3><p>${meta}</p><span class="tag">Reporte disponible</span></div><div class="actions"><strong>${score}</strong>${goButton('Ver reporte','report','secondary')}</div></div>`).join('');
}
function publicShell(content){return `<header class="public-header">${brand()}<nav><a href="#landing">Cómo funciona</a>${goButton('Iniciar sesión','login','secondary')}</nav></header><main id="content">${content}</main><footer class="public-footer">Thropic · Talki · Práctica de comunicación oral en español. ${goButton('Privacidad','privacy','text')}${goButton('Términos de uso','terms','text')}</footer>`;}
function shell(content){return `<div class="shell"><aside class="sidebar">${brand()}<nav aria-label="Principal">${nav.map(([id,icon,label])=>`<a class="nav-item ${demo.screen===id?'active':''}" ${demo.screen===id?'aria-current="page"':''} href="#${id}"><span class="nav-icon" aria-hidden="true">${icon}</span>${label}</a>`).join('')}</nav><div class="sidebar-bottom"><strong>Tu práctica, tus datos.</strong><p>Controla lo que compartes y cuándo lo eliminas.</p>${goButton('Ver privacidad','privacy','text')}${goButton('Notificaciones','preferences','text')}${button('Cerrar sesión','logout','text')}</div></aside><div class="workspace"><header class="app-header"><span class="breadcrumb">Talki / ${screenNames[demo.screen]}</span><div class="avatar"><span aria-hidden="true">VR</span><small>Valeria · Persona de diseño</small></div></header><main id="content" class="page-content">${content}</main></div></div><nav class="mobile-nav" aria-label="Principal móvil">${nav.map(([id,icon,label])=>`<a href="#${id}" class="${demo.screen===id?'active':''}" ${demo.screen===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}</a>`).join('')}</nav>`;}
function auth(kind){
 const register=kind==='register', recovery=kind==='recovery';
 return publicShell(`<div class="auth-wrap"><section class="auth-story"><div class="eyebrow" style="color:#fff">De la idea a la voz</div><h2>Practica hoy.<br>Habla con más claridad.</h2><p>Un espacio para ensayar, reconocer oportunidades y preparar tu siguiente presentación.</p>${wave()}</section><form id="auth-form" class="auth-form"><h1 tabindex="-1">${recovery?'Recuperar acceso':register?'Crea tu cuenta':'Qué bueno verte'}</h1><p>${recovery?'Te mostraremos una confirmación sin revelar si el correo está registrado.':'Continúa con el flujo de demostración de Talki.'}</p>${register?field('Nombre','name','text','','required autocomplete="name"'):''}${field('Correo electrónico','email','email','','required autocomplete="email"')}${!recovery?field('Contraseña','password','password','','required minlength="8" autocomplete="'+(register?'new-password':'current-password')+'"'):''}${register?`<label class="check"><input type="checkbox" required> <span>Acepto las condiciones de uso. El consentimiento para procesar voz se solicita antes de cada práctica.</span></label>`:''}<button type="submit">${recovery?'Enviar instrucciones':register?'Crear cuenta':'Iniciar sesión'}</button>${!register&&!recovery?`<p style="margin-top:16px">${goButton('Olvidé mi contraseña','recovery','text')}</p>`:''}<p style="margin-top:20px">${goButton(register?'Ya tengo cuenta':'Crear cuenta',register?'login':'register','text')}</p><small>Demostración: no se envía, guarda ni verifica ninguna credencial.</small></form></div>`);
}
const screens = {
 landing:()=>publicShell(`<section class="hero"><div><div class="eyebrow">Tu voz tiene algo que decir</div><h1>Ensaya tus ideas.<br><em>Hazlas escuchar.</em></h1><p>Practica exposiciones, entrevistas y sustentaciones con acompañamiento y feedback que puedes convertir en acciones.</p><div class="actions">${goButton('Empezar a practicar →','register')}${goButton('Explorar demostración','dashboard','secondary')}</div><p style="font-size:13px;margin-top:19px">En español · Web y móvil · Control de tus datos</p></div><div class="hero-preview"><div class="flex-between"><h3>Tu siguiente paso</h3><span class="pill">Reporte de ejemplo</span></div><div class="score-large">79<small>/100</small></div><p>Una acción concreta para tu próximo ensayo.</p>${wave()}<div class="suggestion"><h3>Deja espacio entre ideas</h3><p>Ensaya una pausa breve al cerrar cada argumento.</p><small>Ejemplo ficticio · Sin análisis real</small></div></div></section><section class="section" id="benefits"><h2>De la primera exposición a tu próxima entrevista</h2><div class="three-grid"><article class="card"><div class="icon-circle" aria-hidden="true">1</div><h3>Prepara tu escenario</h3><p>Elige modo, duración y enfoque. Para entrevistas puedes añadir material contextual.</p></article><article class="card"><div class="icon-circle" aria-hidden="true">2</div><h3>Practica sin perder el hilo</h3><p>Señales discretas y transcripción. Tú controlas pausa, cierre y privacidad.</p></article><article class="card"><div class="icon-circle" aria-hidden="true">3</div><h3>Decide cómo mejorar</h3><p>Revisa métricas con evidencia y convierte una recomendación en tu siguiente práctica.</p></article></div></section><section class="section"><div class="two-grid"><div class="card"><h2>Para tus primeros ciclos</h2><p>Ensayos guiados, lenguaje claro y recomendaciones breves para exposiciones de clase.</p></div><div class="card"><h2>Para retos profesionales</h2><p>Entrevistas y sustentaciones contextualizadas con preguntas y repreguntas.</p></div></div></section><section class="section"><h2>Planes del producto</h2><div class="two-grid"><div class="card"><h3>Acceso básico</h3><p>La propuesta freemium considera práctica y feedback inicial. Límites por definir.</p></div><div class="card"><h3>Práctica avanzada</h3><p>La propuesta premium considera simulación y seguimiento. Precio y disponibilidad por validar.</p></div></div><p style="margin-top:16px">Los planes son una propuesta de diseño; este prototipo no cobra ni habilita suscripciones.</p><div class="card"><h3>¿Tienes una pregunta?</h3><form id="contact-form">${field('Tu correo','contact-email','email','','required')}${field('Consulta','contact-message','text','','required')}<button type="submit">Enviar consulta de prueba</button></form></div></section>`),
 register:()=>auth('register'),login:()=>auth('login'),recovery:()=>auth('recovery'),
 dashboard:()=>shell(head('Hola, Valeria.','Cada ensayo es una oportunidad para ordenar tus ideas.',goButton('＋ Nueva práctica','setup'))+`<div class="stats"><div class="card stat"><div class="eyebrow">Ejemplo de sesiones</div><div class="value">${demo.deleted?'0':'5'}</div><small>Esta semana · Datos ficticios</small></div><div class="card stat"><div class="eyebrow">Ejemplo de score</div><div class="value">${demo.deleted?'Sin evidencia':'79'}</div><small>Rúbrica 1.0 · No es una nota</small></div><div class="card stat"><div class="eyebrow">Ejemplo de racha</div><div class="value">${demo.deleted?'0':'3'} días</div><small>Solo cuentan prácticas válidas</small></div></div><div class="two-grid"><div class="card welcome"><span class="pill" style="background:#fff;color:var(--primary)">Tu siguiente ensayo</span><h2 style="margin-top:17px">Una idea. Cinco minutos.<br>Un paso adelante.</h2><p>Prueba una exposición breve y enfócate en cerrar cada argumento con una pausa.</p>${goButton('Preparar mi práctica','setup')}</div><div class="card"><div class="flex-between"><h2>Tu evolución</h2><span class="tag muted">Ejemplo</span></div>${chart()}${goButton('Ver progreso','progress','text')}</div></div><div class="card" style="margin-top:22px"><div class="flex-between"><h2>Prácticas recientes</h2>${goButton('Ver historial','history','text')}</div>${sessionRows()}</div>`),
 profile:()=>shell(head('Tu perfil','Adapta la experiencia a tus objetivos, sin limitar los modos que puedes practicar.')+`<form id="profile-form" class="card"><div class="form-grid">${field('Nombre mostrado','profile-name','text','Valeria Ríos','required')}${field('Universidad (opcional)','university','text','Universidad de ejemplo')}${field('Carrera (opcional)','career','text','Ingeniería de Software')}<div class="field"><label for="profile-segment">Etapa académica</label><select id="profile-segment"><option ${demo.segment==='Ciclos 1–5'?'selected':''}>Ciclos 1–5</option><option ${demo.segment==='Ciclos 6–10'?'selected':''}>Ciclos 6–10</option></select></div></div>${field('Meta de mejora','profile-goal','text',demo.goal)}<button type="submit">Guardar perfil de prueba</button>${goButton('Privacidad y datos','privacy','text')}${goButton('Notificaciones','preferences','text')}</form>`),
 setup:()=>shell(head('Prepara tu práctica','Elige el escenario que quieres ensayar. Podrás cancelar antes de empezar.')+`<div class="stepper"><div class="step active"><span>1</span> Configurar</div><div class="step"><span>2</span> Audio y privacidad</div><div class="step"><span>3</span> Practicar</div></div><form id="setup-form" class="card"><h2>¿Qué vas a practicar?</h2><div class="radio-grid">${[['Exposición','Organiza y comunica un tema de clase.'],['Pitch','Presenta una idea de forma breve.'],['Entrevista','Responde preguntas contextualizadas.'],['Sustentación','Defiende argumentos ante repreguntas.']].map(([mode,desc])=>`<label class="mode-option"><input type="radio" name="mode" value="${mode}" ${demo.mode===mode?'checked':''}><span><strong>${mode}</strong><small>${desc}</small></span></label>`).join('')}</div><div class="form-grid">${field('Título del ensayo','session-title','text',demo.title,'required maxlength="120"')}<div class="field"><label for="duration">Duración objetivo</label><select id="duration"><option value="3">3 minutos</option><option value="5" selected>5 minutos</option><option value="10">10 minutos</option><option value="20">20 minutos</option></select></div></div>${field('Meta para este ensayo','session-goal','text',demo.goal,'required')}<div class="field"><label for="focus">Área de enfoque</label><select id="focus"><option>Fluidez y pausas</option><option>Claridad</option><option>Volumen</option><option>Vocabulario</option></select></div><div class="field"><label for="material">Material de contexto (opcional)</label><input id="material" type="file" accept=".pdf,.txt,.pptx"><small>Propuesta: PDF, TXT o PPTX, máximo 10 MB. El prototipo solo muestra el nombre; no lee ni envía el archivo.</small><div id="material-name">${escapeHtml(demo.material)}</div>${button('Quitar material','remove-material','text')}</div>${note('Elegir un modo explica sus criterios. El segmento adapta el lenguaje del feedback, no bloquea funciones.')}<div class="actions">${goButton('Cancelar','dashboard','secondary')}<button type="submit">Continuar a audio →</button></div></form>`),
 microphone:()=>shell(head('Comprueba el audio','Antes de practicar, revisa qué información se procesa y valida tu entrada de voz.')+`<div class="stepper"><div class="step"><span>1</span> Configurar</div><div class="step active"><span>2</span> Audio y privacidad</div><div class="step"><span>3</span> Practicar</div></div><div class="two-grid"><div class="card"><h2>Prueba de micrófono</h2><p>Habla una frase corta para comprobar el nivel de entrada en la aplicación final.</p><div class="meter"><span style="width:${demo.mic?'68':'0'}%"></span></div><p id="mic-state">${demo.mic?'Prueba simulada correcta. Nivel suficiente.':'Aún no has probado el audio.'}</p><div class="actions">${button('Simular prueba correcta','mic-ok')}${button('Simular permiso denegado','mic-denied','secondary')}</div><small>Esta demostración no solicita ni captura audio.</small></div><div class="card"><h2>Tú decides sobre tus datos</h2><ul class="details-list"><li>La voz se procesa para transcripción, coaching y análisis autorizados.</li><li>El audio crudo no se conserva por defecto.</li><li>El transcript y feedback se guardan para tu historial.</li><li>El material de contexto solo se utiliza si lo autorizas.</li><li>Puedes revocar acceso y solicitar eliminación desde Privacidad.</li></ul><label class="check"><input id="consent" type="checkbox" ${demo.consent?'checked':''}><span>Autorizo el procesamiento de esta práctica y su material para las finalidades descritas (política propuesta v1.0).</span></label></div></div><div class="actions" style="margin-top:22px">${goButton('Volver a configuración','setup','secondary')}<button type="button" data-action="start-live" ${demo.mic&&demo.consent?'':'disabled'}>Iniciar práctica</button></div>`),
 live:()=>shell(head(escapeHtml(demo.title),`${escapeHtml(demo.mode)} · Objetivo ${demo.duration} min · Demostración sin grabación`,button(demo.muted?'Activar señales':'Silenciar señales','mute','secondary'))+`${demo.disconnected?'<div class="notice warning">Conexión interrumpida. El último checkpoint confirmado se conserva. Reanuda o finaliza con resultado parcial.</div>':''}<div class="two-grid"><section class="live-panel"><span class="tag ${demo.paused||demo.disconnected?'warning':''}">${demo.disconnected?'Interrumpida':demo.paused?'En pausa':'Práctica activa de ejemplo'}</span><div class="timer">02:34 <small style="font-size:17px;color:var(--muted)">/ ${String(demo.duration).padStart(2,'0')}:00</small></div>${wave()}<p>${demo.mode==='Entrevista'||demo.mode==='Sustentación'?'Pregunta de ejemplo: ¿Cómo justificas la decisión principal de tu proyecto?':'Habla con calma. Las señales son discretas y puedes silenciarlas.'}</p>${!demo.muted?'<div class="notice">Señal de ejemplo: cierra la idea y deja una pausa breve.</div>':''}<div class="live-controls">${button(demo.paused?'Reanudar':'Pausar','pause','secondary')}${button('Finalizar práctica','finish','danger')}</div></section><section class="card"><h2>Transcripción en vivo</h2><span class="pill">Contenido ficticio</span><div class="transcript"><small>02:12 · Fragmento confirmado</small>El objetivo de nuestro proyecto es ayudar a estudiantes a practicar su comunicación oral con recomendaciones concretas.</div><p>El último fragmento confirmado puede recuperarse. Lo que no se confirmó antes de una desconexión puede perderse.</p><div class="actions">${button(demo.disconnected?'Reanudar conexión':'Simular desconexión',demo.disconnected?'reconnect':'disconnect','secondary')}</div></section></div>`),
 processing:()=>shell(head('Tu reporte está en camino','El estado distingue espera, procesamiento, reporte disponible y fallo recuperable.')+`<section class="card" style="max-width:760px;margin:auto"><h2>${demo.analysisFailed?'Análisis interrumpido':'Analizando el ensayo de ejemplo'}</h2><div class="meter"><span style="width:${demo.analysisFailed?'45':'75'}%;background:${demo.analysisFailed?'var(--danger)':'var(--primary)'}"></span></div><ul class="details-list"><li>Transcripción consolidada · Completa</li><li>Métricas de discurso · ${demo.analysisFailed?'Fallo recuperable':'En proceso'}</li><li>Feedback con evidencia · Pendiente</li></ul>${demo.analysisFailed?'<div class="notice warning">No se pudo completar el análisis. Puedes reintentar sobre la misma sesión sin crear un reporte duplicado.</div>':note('Puedes volver al historial. El objetivo de diseño es disponer del 95 % de reportes en ≤ 60 s; todavía debe medirse con el producto.')}<div class="actions">${button(demo.analysisFailed?'Reintentar análisis':'Simular reporte disponible',demo.analysisFailed?'retry':'complete')}${button('Simular fallo','analysis-fail','secondary')}${button('Simular evidencia insuficiente','insufficient','secondary')}${goButton('Ir al historial','history','text')}</div></section>`),
 report:()=>demo.deleted?shell(head('Reporte no disponible','El recurso fue retirado y no puede consultarse.')+note('La eliminación lógica bloquea el acceso; la purga física se muestra en Privacidad.')+goButton('Ver privacidad','privacy')):shell(head('De la práctica a la acción',`${escapeHtml(demo.title)} · ${escapeHtml(demo.mode)} · Datos ficticios`,goButton('Practicar de nuevo','setup'))+`${demo.insufficient?'<div class="notice warning">Resultado parcial: evidencia insuficiente. No se calcula una puntuación global ni dimensiones sin soporte.</div>':''}<div class="two-grid"><section class="card"><div class="flex-between"><h2>Voice Coach Score</h2><span class="pill">Ejemplo ficticio</span></div><div class="score-large">${demo.insufficient?'Sin evidencia':'79'}<small>${demo.insufficient?'':'/100'}</small></div><p>${demo.insufficient?'Sin evidencia para score global.':'Referencia para practicar, no una calificación académica.'}</p>${dimensions(demo.insufficient)}<small>Análisis v1.0 · Rúbrica exposición v1.0 · Confianza es una estimación de señales del discurso.</small></section><section class="card"><h2>Tu próxima acción</h2><div class="suggestion"><h3>1. Da espacio a cada argumento</h3><p>Observación de ejemplo: varias ideas aparecen sin pausa de cierre.</p><p><strong>Evidencia ficticia:</strong> 01:10–01:25, «la solución… además… también…».</p><p><strong>Acción:</strong> ensaya una pausa breve al cerrar cada argumento.</p></div><div class="suggestion"><h3>2. Reduce una muletilla</h3><p>Ejemplo: «este» aparece 6 veces. Prueba una pausa en lugar de repetirla.</p></div><div class="actions" style="margin-top:20px">${goButton('Ver plan de práctica','plan','secondary')}${goButton('Compartir y exportar','privacy','secondary')}</div></section></div><section class="card" style="margin-top:22px"><h2>Transcripción y evidencia</h2><p>Los términos usados y sugeridos se distinguen. El feedback prioriza pocas acciones y no sustituye vocabulario técnico correcto.</p><div class="transcript"><small>00:40–00:55 · Fragmento ficticio</small>La solución permite ensayar y luego revisar recomendaciones para preparar la siguiente exposición.</div><span class="tag muted">Palabra usada: comunicación</span> <span class="tag muted">Sugerencia contextual: claridad</span></section>`),
 history:()=>shell(head('Tu historial','Recupera reportes propios y encuentra la práctica que quieres revisar.',goButton('Nueva práctica','setup'))+`<div class="card"><div class="search-bar"><div class="field"><label for="history-search">Buscar por título</label><input id="history-search" type="search" placeholder="Ej.: exposición"></div><div class="field"><label for="history-mode">Modo</label><select id="history-mode"><option>Todos</option><option>Exposición</option><option>Pitch</option></select></div></div><div id="history-results">${sessionRows()}</div><div class="actions" style="margin-top:18px">${goButton('Comparar dos prácticas','compare','secondary')}${goButton('Ver progreso','progress','text')}</div></div>`),
 progress:()=>shell(head('Observa tu evolución','Compara evidencia compatible y elige una acción para tu siguiente ensayo.',goButton('Comparar sesiones','compare','secondary'))+`${demo.deleted?note('El recurso eliminado ya no participa en la tendencia de este recorrido.'):''}<div class="two-grid"><section class="card"><div class="flex-between"><h2>Voice Coach Score · Ejemplo</h2><span class="tag muted">Rúbrica 1.0</span></div>${demo.deleted?'<div class="empty">Sin datos en el recorrido reiniciado.</div>':chart()}<p style="font-size:13px">Valores ficticios: 65, 71, 68, 76 y 79. La variación no demuestra mejora causal ni se mezcla con rúbricas incompatibles.</p></section><section class="card"><h2>Un enfoque para esta semana</h2><p>Ejemplo de patrón recurrente: cerrar ideas sin una pausa.</p><div class="suggestion"><h3>Ensayo de tres argumentos</h3><p>Practica 3 minutos y deja una pausa breve después de cada argumento.</p><small>Base de ejemplo: reportes S3 y S5, análisis y rúbrica v1.0.</small></div>${goButton('Abrir plan adaptativo','plan','text')}</section></div>`),
 compare:()=>shell(head('Compara dos prácticas','La compatibilidad de modo, rúbrica y análisis debe verificarse antes de calcular diferencias.')+`<section class="card"><div class="form-grid"><div class="field"><label for="compare-a">Primera sesión</label><select id="compare-a"><option>Exposición S3 · Score ficticio 68 · Rúbrica 1.0</option></select></div><div class="field"><label for="compare-b">Segunda sesión</label><select id="compare-b"><option value="compatible">Exposición S5 · Score ficticio 79 · Rúbrica 1.0</option><option value="incompatible">Entrevista · Rúbrica 2.0 (incompatible)</option></select></div></div><div id="compare-result">${note('Ejemplo compatible: diferencia +11 puntos. Revisa la evidencia y el tamaño de muestra; una variación aislada no demuestra una mejora sostenida.')}</div>${goButton('Ver plan','plan')}</section>`),
 plan:()=>shell(head('Un plan para tu próxima práctica','Cada ejercicio explica qué patrón intenta trabajar.')+`<div class="two-grid"><section class="card"><span class="pill">Propuesta de ejercicio</span><h2 style="margin-top:18px">Tres argumentos, tres pausas</h2><p>Prepara una idea con tres argumentos. Haz una pausa breve al cerrar cada uno y repite el ensayo durante tres minutos.</p><div class="notice">Motivo de ejemplo: pausas de cierre ausentes en S3 y S5, bajo la misma rúbrica y análisis.</div><label class="check"><input id="plan-done" type="checkbox" ${demo.planDone?'checked':''}><span>He estudiado este ejercicio en la demostración.</span></label>${goButton('Practicar este ejercicio','setup')}</section><section class="card"><h2>Si aún no tienes historial</h2><p>Empieza con una práctica inicial. El producto no puede atribuirte errores recurrentes sin evidencia suficiente.</p><h3>La recomendación debe poder explicarse</h3><p>Dimensión, periodo, sesiones fuente, versiones y acción concreta acompañan a cada ejercicio.</p></section></div>`),
 privacy:()=>shell(head('Tu práctica, bajo tu control','Compartir, revocar y eliminar son acciones distintas.')+`<div class="two-grid"><section class="card"><h2>Compartir un reporte</h2><p>Un tutor puede consultar solo este reporte, con acceso de lectura y expiración. Una copia descargada no puede recuperarse.</p><div class="field"><label for="share-duration">Vigencia propuesta</label><select id="share-duration"><option>24 horas</option><option>7 días</option></select></div><div class="actions">${button('Crear enlace de ejemplo','share')}${button('Revocar enlace','revoke','secondary')}</div><div id="share-state">${demo.deleted?note('Este recurso fue eliminado; no puede compartirse.'):demo.shared&&!demo.revoked?note('Enlace de ejemplo activo. No concede acceso real ni envía datos.')+goButton('Ver como tutor','shared','text'):note(demo.revoked?'El enlace fue revocado. El tutor pierde el acceso.':'Aún no has creado un enlace en este recorrido.')}</div>${button('Exportar reporte de ejemplo','export','secondary')}</section><section class="card"><h2>Consentimiento y eliminación</h2><p>Retirar consentimiento detiene nuevo procesamiento del alcance revocado. Eliminar retira el recurso y activa su purga.</p><div class="actions">${button('Revocar consentimiento','withdraw','secondary')}${button('Eliminar sesión de ejemplo','delete','danger')}</div>${demo.deleted?'<div class="notice warning">Acceso bloqueado · Purga física pendiente. En el producto se confirmará al recibir los recibos de todos los contextos.</div>':note('Audio crudo: sin conservación por defecto. Transcript y feedback: bajo tu control. La política final de retención debe acordarse antes de operar.')}<h3>Privacidad sin sorpresas</h3><p>Los reportes compartidos no incluyen otras sesiones, documentos de contexto ni acceso a tu cuenta.</p></section></div>`),
 shared:()=>publicShell(`<section class="section"><h1 tabindex="-1">${demo.deleted||demo.revoked||!demo.shared?'Enlace no disponible':'Reporte compartido · Solo lectura'}</h1>${demo.deleted||demo.revoked||!demo.shared?'<div class="notice warning">El enlace no existe, fue revocado o expiró. No se muestra información del reporte.</div>':`<div class="card"><span class="pill">Ejemplo ficticio · Acceso limitado</span><h2 style="margin-top:18px">Exposición: proyecto de curso</h2><div class="score-large">79<small>/100</small></div><p>Rúbrica v1.0 · Análisis v1.0 · Vigencia de ejemplo: 24 horas</p><div class="suggestion"><h3>Siguiente acción de ejemplo</h3><p>Dejar una pausa breve al cerrar cada argumento.</p></div><p style="margin-top:20px">No puedes editar ni consultar otras sesiones.</p></div>`}${goButton('Volver a privacidad','privacy','secondary')}</section>`),
 preferences:()=>shell(head('Tus notificaciones','Decide si quieres recibir avisos opcionales. Los mensajes de seguridad tienen otra finalidad.')+`<section class="card"><label class="check"><input id="optional-email" type="checkbox" ${demo.optionalEmail?'checked':''}><span>Recibir avisos opcionales de reportes y práctica por correo.</span></label>${note('Verificación de cuenta y recuperación de acceso son mensajes transaccionales. Ningún correo de reporte debe incluir transcript, score o documentos privados.')}<p>Esta preferencia se mantiene solo mientras exploras el prototipo.</p></section>`)
};
// En escritorio, las pantallas ya disponibles usan sus capturas originales.
// La vista móvil y los wireframes son propuestas de distribución; no una app nativa publicada.
const referenceScreens = {
 login: ['01-login.png', 'Acceso de Talki', () => goButton('Explorar complementos', 'privacy', 'secondary')],
 dashboard: ['02-dashboard.png', 'Dashboard de Talki', () => goButton('Configurar sesión', 'setup') + goButton('Privacidad y acceso', 'privacy', 'secondary')],
 setup: ['03-coach.png', 'Live Coach de Talki', () => button('Explorar material contextual', 'extend-setup') + goButton('Preparar audio y consentimiento', 'microphone', 'secondary')],
 live: ['08-session-recording.png', 'Grabación de una sesión de Talki', () => button('Explorar desconexión', 'disconnect', 'secondary') + button('Explorar cierre y análisis', 'finish')],
 report: ['09-session-ai-feedback.png', 'Feedback de sesión de Talki', () => goButton('Compartir o eliminar', 'privacy') + goButton('Comparar sesiones', 'compare', 'secondary')],
 history: ['04-sessions.png', 'Sesiones de Talki', () => goButton('Consultar feedback', 'report') + goButton('Comparar sesiones', 'compare', 'secondary')]
};
for (const [id, [file, title, actions]] of Object.entries(referenceScreens)) {
 const proposedView = screens[id];
 screens[id] = () => {
  const variant = (id === 'setup' && demo.extensionSetup) || (id === 'live' && demo.disconnected) || (id === 'report' && (demo.insufficient || demo.deleted)) || (id === 'history' && demo.deleted);
  if (params.get('reference') !== '1' || innerWidth <= 700 || document.body.classList.contains('wireframe') || variant) return proposedView();
  return `<main id="content" class="reference-view"><h1 tabindex="-1">${title}</h1><p class="reference-note">Captura de referencia del cliente web. Para utilizar sus funciones, abre Talki. Las acciones de abajo permiten explorar los complementos de diseño con datos ficticios.</p><div class="reference-tools"><a class="button" href="https://talki-frontend.vercel.app" target="_blank" rel="noopener noreferrer">Abrir Talki</a>${actions()}</div><img class="reference-image" src="../../reused-202601/frontend/${file}" alt="${title}"><div class="reference-tools">${goButton('Volver a los complementos', 'privacy', 'secondary')}</div></main>`;
 };
}


screens.terms=()=>publicShell(head('Términos de uso de Talki','Propuesta de condiciones para el diseño del servicio.')+`<section class="section card"><h2>Finalidad y límites</h2><p>Talki permite preparar y ensayar comunicación oral con apoyo de inteligencia artificial. El feedback orienta la práctica; no constituye nota académica, diagnóstico ni garantía de mejora. Una dimensión sin evidencia se presenta como tal.</p><h2>Voz, material y consentimiento</h2><p>El procesamiento requiere autorización explícita y versionada. El estudiante solo debe aportar material que pueda utilizar legítimamente. Retirar consentimiento bloquea nuevas prácticas; eliminar una sesión solicita el retiro de sus datos.</p><h2>Acceso y compartición</h2><p>Los reportes son privados por defecto. Compartir concede lectura limitada y temporal; revocar impide consultas futuras, pero no recupera copias descargadas. La eliminación muestra su estado hasta confirmar la purga.</p><h2>Uso responsable</h2><p>El estudiante conserva la responsabilidad de revisar recomendaciones y mantener contexto y contenido propios. El producto debe permitir reportar errores y evitar atribuciones sobre emociones o capacidades que no pueda sustentar.</p><h2>Estado de estas condiciones</h2><p>Este texto es una propuesta de diseño, sin contratación, cobro ni tratamiento real de datos en el prototipo. Las condiciones definitivas identificarán al responsable, contacto, retención y derechos antes de operar.</p>${goButton('Volver al inicio','landing','secondary')}</section>`);

let toastTimer;
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,5500);}
function render(screen,focus=true){demo.screen=screens[screen]?screen:'landing';app.innerHTML=screens[demo.screen]();if(!['landing','register','login','recovery','terms'].includes(demo.screen)){document.querySelector('.workspace')?.insertAdjacentHTML('beforeend',`<footer class="product-footer">${goButton('Términos de uso','terms','text')}${goButton('Privacidad','privacy','text')}</footer>`);}document.title=`Talki · ${screenNames[demo.screen]}`;wireForms();if(focus){window.scrollTo(0,0);app.querySelector('h1')?.focus({preventScroll:true});}}
function go(screen){if(location.hash===`#${screen}`)render(screen);else location.hash=screen;}
function confirmation(title,body,callback){const dialog=document.getElementById('confirm-dialog');document.getElementById('dialog-title').textContent=title;document.getElementById('dialog-body').textContent=body;document.getElementById('dialog-confirm').onclick=()=>{dialog.close();callback();};dialog.showModal();}
document.getElementById('dialog-cancel').onclick=()=>document.getElementById('confirm-dialog').close();
function wireForms(){
 const duration=document.getElementById('duration');if(duration)duration.value=String(demo.duration);
 for(const [id,key] of [['session-title','title'],['session-goal','goal']])document.getElementById(id)?.addEventListener('input',e=>demo[key]=e.target.value);
 duration?.addEventListener('change',e=>demo.duration=Number(e.target.value));
 document.querySelectorAll('[name=mode]').forEach(el=>el.addEventListener('change',e=>demo.mode=e.target.value));
 document.getElementById('auth-form')?.addEventListener('submit',e=>{e.preventDefault();if(demo.screen==='recovery')toast('Si existe una cuenta, recibirá instrucciones. En este prototipo no se envía correo.');else if(demo.screen==='register'){go('profile');toast('Registro simulado. En el producto se solicitará verificación del correo.');}else go('dashboard');});
 document.getElementById('contact-form')?.addEventListener('submit',e=>{e.preventDefault();toast('Consulta de prueba confirmada. No se envió ningún mensaje.');e.target.reset();});
 document.getElementById('profile-form')?.addEventListener('submit',e=>{e.preventDefault();demo.segment=document.getElementById('profile-segment').value;demo.goal=document.getElementById('profile-goal').value;toast('Perfil de prueba actualizado durante este recorrido.');go('dashboard');});
 document.getElementById('setup-form')?.addEventListener('submit',e=>{e.preventDefault();demo.title=document.getElementById('session-title').value;demo.goal=document.getElementById('session-goal').value;demo.duration=Number(document.getElementById('duration').value);demo.mode=document.querySelector('[name=mode]:checked').value;demo.mic=false;demo.consent=false;go('microphone');});
 document.getElementById('material')?.addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024||!(/\.(pdf|txt|pptx)$/i).test(file.name)){e.target.value='';demo.material='';document.getElementById('material-name').textContent='';toast('Usa PDF, TXT o PPTX de hasta 10 MB.');return;}demo.material=file.name;document.getElementById('material-name').textContent=`Material autorizado de ejemplo: ${file.name}`;});
 document.getElementById('consent')?.addEventListener('change',e=>{demo.consent=e.target.checked;document.querySelector('[data-action=start-live]').disabled=!(demo.mic&&demo.consent);});
 document.getElementById('compare-b')?.addEventListener('change',e=>{document.getElementById('compare-result').innerHTML=e.target.value==='incompatible'?'<div class="notice warning">No se pueden comparar: modo y versión de rúbrica diferentes. Elige sesiones compatibles.</div>':note('Diferencia ficticia +11 puntos; no demuestra mejora sostenida por sí sola.');});
 document.getElementById('optional-email')?.addEventListener('change',e=>{demo.optionalEmail=e.target.checked;toast('Preferencia de ejemplo actualizada.');});
 document.getElementById('plan-done')?.addEventListener('change',e=>demo.planDone=e.target.checked);
 for(const id of ['history-search','history-mode'])document.getElementById(id)?.addEventListener('input',()=>{const query=document.getElementById('history-search').value.toLowerCase();const mode=document.getElementById('history-mode').value;document.querySelectorAll('#history-results .session-row').forEach(row=>{row.hidden=!row.textContent.toLowerCase().includes(query)||(mode!=='Todos'&&!row.textContent.includes(mode));row.style.display=row.hidden?'none':'';});});
}
app.addEventListener('click',e=>{
 const control=e.target.closest('[data-action]');if(!control)return;const action=control.dataset.action;
 if(action.startsWith('go:'))return go(action.slice(3));
 if(action==='extend-setup'){demo.extensionSetup=true;render('setup');return;}
 if(action==='remove-material'){demo.material='';render(demo.screen,false);}
 if(action==='mic-ok'){demo.mic=true;render('microphone',false);toast('Nivel de entrada simulado correcto.');}
 if(action==='mic-denied'){demo.mic=false;render('microphone',false);document.getElementById('mic-state').textContent='Permiso denegado: habilita micrófono desde los permisos del dispositivo y vuelve a probar.';}
 if(action==='start-live'&&demo.mic&&demo.consent){Object.assign(demo,{paused:false,disconnected:false,completed:false,insufficient:false,deleted:false});go('live');}
 if(action==='pause'){if(demo.disconnected)return toast('Primero reanuda la conexión o cierra parcialmente.');demo.paused=!demo.paused;render('live',false);}
 if(action==='mute'){demo.muted=!demo.muted;render('live',false);}
 if(action==='disconnect'){demo.disconnected=true;render('live',false);}
 if(action==='reconnect'){demo.disconnected=false;demo.paused=false;render('live',false);toast('Checkpoint de ejemplo recuperado sin duplicar transcripción.');}
 if(action==='finish')confirmation('¿Finalizar esta práctica?',demo.disconnected?'Se conservará un resultado parcial con la evidencia confirmada.':'Se guardará la transcripción autorizada y comenzará el análisis.',()=>{demo.insufficient=demo.disconnected;demo.completed=true;demo.analysisFailed=false;go('processing');});
 if(action==='analysis-fail'){demo.analysisFailed=true;render('processing',false);}
 if(action==='retry'){demo.analysisFailed=false;render('processing',false);toast('Reintento de ejemplo sobre el mismo análisis.');}
 if(action==='complete'){demo.completed=true;go('report');}
 if(action==='insufficient'){demo.insufficient=true;go('report');}
 if(action==='share'){if(demo.deleted)return toast('No se puede compartir un recurso eliminado.');demo.shared=true;demo.revoked=false;render('privacy',false);}
 if(action==='revoke'){demo.revoked=true;render('privacy',false);toast('El enlace de ejemplo ya no permite acceso.');}
 if(action==='delete')confirmation('¿Eliminar la sesión de ejemplo?','Se bloquearán accesos y enlaces. La purga física permanecerá pendiente de confirmación.',()=>{demo.deleted=true;demo.revoked=true;demo.material='';render('privacy');toast('Eliminación lógica de ejemplo completada; purga pendiente.');});
 if(action==='withdraw')confirmation('¿Revocar el consentimiento?','No podrás iniciar una nueva práctica sin autorizar el procesamiento. No equivale a eliminar el historial.',()=>{demo.consent=false;toast('Consentimiento de ejemplo revocado.');});
 if(action==='export'){if(demo.deleted)return toast('El recurso fue eliminado; no puede exportarse.');const blob=new Blob(['TALKI · REPORTE DE EJEMPLO FICTICIO\nNo es un análisis real ni una nota académica.\nScore: '+(demo.insufficient?'Sin evidencia':'79/100')+'\nAnálisis v1.0 · Rúbrica v1.0\nAcción de ejemplo: dejar una pausa al cerrar argumentos.'],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='talki-reporte-ejemplo.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exportación de ejemplo: solo incluye datos ficticios.');}
 if(action==='logout')confirmation('¿Cerrar sesión?',demo.screen==='live'?'Hay una práctica activa en la demostración. Confirma antes de salir.':'Se cerrará el recorrido de ejemplo.',()=>go('login'));
});
window.addEventListener('hashchange',()=>render(location.hash.slice(1)));
window.matchMedia('(max-width: 700px)').addEventListener('change',()=>render(demo.screen,false));
render(location.hash.slice(1)||params.get('screen')||'privacy',false);
